command:
// ==========================================
// LUNAS WIRKUNG: STRENGE MUTTER (NURTI)
//
// - 1 gültiges erwachtes Ziel (nicht der Wirkende selbst)
// - alle weiteren / ungültigen Targets = Misserfolg, Gabe geht dennoch durch
// - Dauer: QS Minuten | Anzahl Fragen: QS
// - Ziel und Wirkender erhalten verknüpfte Effekte (inkl. gekoppelter Lösch-Kette)
// - gespeichertes Ziel | GM-Button | Framework-Effektanlage über Block 6 & 7
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Strenge Mutter")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Target?.Merken ||
        !globalThis.DSK?.Target?.Finden || !globalThis.DSK?.Target?.Actor ||
        !globalThis.DSK?.Wesen?.match ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register || !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde || !DSK_FW?.Target?.Merken ||
        !DSK_FW?.Target?.Finden || !DSK_FW?.Target?.Actor ||
        !DSK_FW?.Wesen?.match ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN & KOPPLUNGS-HOOK +++++++++++++++++++++++++
    const gabenName = "Strenge Mutter", vollerName = "Strenge Mutter (Nurti)", ahne = "Nurti";
    const flagKey = "pendingStrengeMutterNurti", endeKey = "nurtiStrengeMutter";
    const endeText = "Die Zeit der zwingenden Wahrheit ist abgelaufen. Der Befragte kann wieder frei entscheiden, was er antwortet.";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // Gekoppeltes Löschen: Wird der Effekt auf einer Seite entfernt, wird auch das Gegenstück gelöscht
    if (globalThis._dskStrengeMutterLinkHook) {
        Hooks.off("deleteActiveEffect", globalThis._dskStrengeMutterLinkHook);
    }
    globalThis._dskStrengeMutterLinkHook = Hooks.on("deleteActiveEffect", async effect => {
        const aktiverGM = game.users.find(u => u.isGM && u.active);
        const darfLoeschen = aktiverGM ? (game.user.isGM && game.user.id === aktiverGM.id) : game.user.isGM;
        if (!darfLoeschen || !effect) return;

        if ((effect.name || effect.label || "") !== vollerName) return;
        if (effect.getFlag("dsk", "isStrengeMutter") !== true) return;

        const linkedUuid = effect.getFlag("dsk", "linkedActorUuid");
        const parentUuid = effect.parent?.uuid;
        if (!linkedUuid || !parentUuid) return;

        try {
            const doc = await fromUuid(linkedUuid);
            const linkedActor = doc?.documentName === "Token" ? doc.actor : doc;
            if (!linkedActor?.effects) return;

            const gekoppelteIds = linkedActor.effects
                .filter(e =>
                    (e.name || e.label || "") === vollerName &&
                    e.getFlag("dsk", "isStrengeMutter") === true &&
                    e.getFlag("dsk", "linkedActorUuid") === parentUuid
                )
                .map(e => e.id);

            if (gekoppelteIds.length) {
                await linkedActor.deleteEmbeddedDocuments("ActiveEffect", gekoppelteIds);
            }
        } catch (error) {
            console.warn("Strenge Mutter: Gekoppeltes Effekt-Cleanup fehlgeschlagen.", error);
        }
    });

    // +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++
    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const istErwacht = actor =>
        Boolean(actor && (
            DSK_FW.Effekt.CheckTarget(actor, "erwachte") ||
            DSK_FW.Wesen.match(actor, ["erwacht", "erwachter", "erwachte", "katze", "katzen"])
        ));

    const ladeZiel = async daten => {
        if (!daten) return { token: null, actor: null };
        const token = await DSK_FW.Target.Finden(daten);
        return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
    };

    const findeEigeneEffekte = (actor, casterUuid) =>
        (actor?.effects || []).filter(e =>
            (e.name || e.label || "") === vollerName &&
            (e.getFlag("dsk", "isStrengeMutter") === true || e.getFlag("dsk", "ahne") === "Nurti") &&
            (!casterUuid || !e.getFlag("dsk", "casterUuid") || e.getFlag("dsk", "casterUuid") === casterUuid)
        );

    const beschreibungFuer = (casterName, targetName, qs) =>
        `<b>${casterName}</b> verströmt die Aura einer strengen Mutter gegenüber <b>${targetName}</b>.` +
        `<br><br>Das Ziel muss dem Nurtikind (und <b>ausschließlich ihm</b>) während der Wirkungsdauer absolut wahrheitsgemäß auf <b>${qs} Frage(n)</b> antworten. ` +
        `Ausweichende Lügen sind unmöglich.` +
        `<br><br><b>Anzahl Fragen:</b> ${qs} (QS) | <b>Zielkategorie:</b> Erwachte`;

    // +++ 4 - VERKNÜPFTE EFFEKTE ANWENDEN ++++++++++++++++++++++++
    const wendeEffekteAn = async ({ casterActor, targetActor, qs }) => {
        if (!casterActor || !targetActor || !istErwacht(targetActor)) return false;

        const casterName = DSK_FW.ResolveTokenName(casterActor) || casterActor.name;
        const targetName = DSK_FW.ResolveTokenName(targetActor) || targetActor.name;
        const dauerSekunden = qs * 60;

        // Alte Effekte desselben Wirkenden auf Ziel und Caster bereinigen
        const zielAlt = findeEigeneEffekte(targetActor, casterActor.uuid);
        if (zielAlt.length) {
            await targetActor.deleteEmbeddedDocuments("ActiveEffect", zielAlt.map(e => e.id));
        }

        const casterAlt = findeEigeneEffekte(casterActor, casterActor.uuid);
        if (casterAlt.length) {
            await casterActor.deleteEmbeddedDocuments("ActiveEffect", casterAlt.map(e => e.id));
        }

        // 1. Effekt auf dem befragten Ziel
        const zielEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName,
            ahne,
            beschreibung:
                `Muss dem Nurtikind (<b>${casterName}</b>) während der Wirkungsdauer auf genau <b>${qs} Frage(n)</b> absolut wahrheitsgemäß antworten.` +
                `<br><br><b>Wirkungsdauer:</b> ${qs} Minute(n)`,
            gabeZiel: "erwachte",
            qs,
            ziel: targetActor,
            changes: [],
            duration: { seconds: dauerSekunden, startTime: game.time.worldTime },
            showIcon: 1,
            flags: {
                dsk: {
                    isStrengeMutter: true,
                    rolle: "ziel",
                    casterUuid: casterActor.uuid,
                    linkedActorUuid: casterActor.uuid,
                    linkedActorName: casterName,
                    qs,
                    anzahlFragen: qs,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });

        if (!zielEffekt) return false;

        // 2. Effekt auf dem Wirkenden (Nurtikind)
        let casterEffekt = null;
        try {
            casterEffekt = await DSK_FW.Effekt.Anwenden({
                name: vollerName,
                ahne,
                beschreibung:
                    `Kann <b>${targetName}</b> genau <b>${qs} Frage(n)</b> stellen, die absolut wahrheitsgemäß beantwortet werden müssen.` +
                    `<br><br><b>Wirkungsdauer:</b> ${qs} Minute(n)`,
                gabeZiel: "erwachte",
                qs,
                ziel: casterActor,
                changes: [],
                duration: { seconds: dauerSekunden, startTime: game.time.worldTime },
                showIcon: 1,
                flags: {
                    dsk: {
                        isStrengeMutter: true,
                        rolle: "wirkender",
                        casterUuid: casterActor.uuid,
                        linkedActorUuid: targetActor.uuid,
                        linkedActorName: targetName,
                        qs,
                        anzahlFragen: qs,
                        wirkungsende: {
                            sfName: endeKey,
                            basisEffektName: vollerName,
                            beschreibungFuerEnde: endeText
                        }
                    }
                }
            });
        } catch (error) {
            console.error("Strenge Mutter: Effekt auf dem Wirkenden fehlgeschlagen.", error);
        }

        if (!casterEffekt) {
            try { await zielEffekt.delete(); } catch {}
            return false;
        }

        const zielEnde = zielEffekt.getFlag("dsk", "wirkungsende");
        const casterEnde = casterEffekt.getFlag("dsk", "wirkungsende");

        return Boolean(
            zielEffekt.parent?.uuid === targetActor.uuid &&
            casterEffekt.parent?.uuid === casterActor.uuid &&
            zielEffekt.getFlag("dsk", "isStrengeMutter") === true &&
            casterEffekt.getFlag("dsk", "isStrengeMutter") === true &&
            zielEffekt.getFlag("dsk", "linkedActorUuid") === casterActor.uuid &&
            casterEffekt.getFlag("dsk", "linkedActorUuid") === targetActor.uuid &&
            Number(zielEffekt.getFlag("dsk", "anzahlFragen")) === qs &&
            zielEnde?.sfName === endeKey &&
            casterEnde?.sfName === endeKey
        );
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++
    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!game.user.isGM || !casterActor || !daten) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
        if (!casterToken) {
            ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
            return false;
        }

        const { token: targetToken, actor: targetActor } = await ladeZiel(daten.target);
        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const targetName = daten.target?.name || targetToken?.name || targetActor?.name || "Unbekanntes Ziel";
        const misserfolge = foundry.utils.deepClone(daten.misserfolge || []);
        let erfolgreich = false;

        if (targetActor && istErwacht(targetActor)) {
            try {
                erfolgreich = await wendeEffekteAn({ casterActor, targetActor, qs });
            } catch (error) {
                console.error("Strenge Mutter: Effektanlage fehlgeschlagen.", {
                    casterActor, targetActor, daten, error
                });
            }
        }

        if (!erfolgreich) {
            misserfolge.unshift({ name: targetName });
        }

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName,
            ahne,
            beschreibung: daten.beschreibung || beschreibungFuer(casterName, targetName, qs),
            wirkender: casterName,
            ziele: erfolgreich ? [{ name: `${targetName} (${qs} ${qs === 1 ? "Frage" : "Fragen"})`, rolle: "Befragtes Ziel" }] : [],
            misserfolge,
            dauerText: `${qs} Minute(n) (${qs} QS)`,
            erfolgreich
        });

        if (erfolgreich) {
            ui.notifications.info(
                `Luna sagt 🌙: Strenge Mutter auf ${targetName} angewendet (${qs} ${qs === 1 ? "Frage" : "Fragen"}).`
            );
        } else {
            ui.notifications.error(
                "Luna sagt 🌙: Strenge Mutter konnte nicht vollständig angewendet werden!"
            );
        }

        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++
    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }

            return;
        }
    }

    // +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 8 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Strenge Mutter Probe", "Strenge Mutter"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Die Aura der strengen Mutter konnte nicht aufgebaut werden.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 9 - ZIEL PRÜFEN (1 GÜLTIGES ERWACHTES ZIEL, ALLE ANDEREN = MISSERFOLG) +++
    const targets = Array.from(game.user.targets || []);

    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!"
        );
    }

    if (targets.length === 1 && targets[0]?.actor?.uuid === casterActor.uuid) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn(
            "Luna sagt 🌙: Das Nurtikind kann sich nicht selbst befragen!"
        );
    }

    let gueltigesZielToken = null;
    const misserfolge = [];

    for (const tToken of targets) {
        const tActor = tToken?.actor;
        const tName = tToken?.name || tActor?.name || "Unbekanntes Ziel";

        if (gueltigesZielToken) {
            misserfolge.push({ name: tName });
            continue;
        }

        if (!tActor || tActor.uuid === casterActor.uuid || !istErwacht(tActor)) {
            misserfolge.push({ name: tName });
            continue;
        }

        gueltigesZielToken = tToken;
    }

    if (!gueltigesZielToken) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Keines der ausgewählten Ziele ist ein gültiger Erwachter.",
            wirkender: casterName,
            ziele: [],
            misserfolge,
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    const targetToken = gueltigesZielToken;
    const targetActor = targetToken.actor;
    const targetName = targetToken.name || targetActor?.name || "Unbekanntes Ziel";
    const targetDaten = DSK_FW.Target.Merken(targetToken);

    if (!targetDaten) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error(
            "Luna sagt 🌙: Das Ziel konnte nicht gespeichert werden!"
        );
    }

    // +++ 10 - KARTE + GM-BUTTON ++++++++++++++++++++++++++++++++++
    const dauerText = `${qs} Minute(n) (${qs} QS)`;
    const beschreibung = beschreibungFuer(casterName, targetName, qs);

    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: [{ name: `${targetName} (${qs} ${qs === 1 ? "Frage" : "Fragen"})`, rolle: "Befragtes Ziel" }],
        misserfolge,
        dauerText,
        gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error(
            "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
        );
    }

    const anfrageDaten = {
        casterUuid: casterActor.uuid,
        casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        target: targetDaten,
        misserfolge,
        qs,
        beschreibung,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id,
        macroUuid,
        erstellt: Date.now()
    };

    // +++ 11 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++
    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        "Luna sagt 🌙: Strenge Mutter wurde bei der Spielleitung zur Anwendung beantragt."
    );
}).call(this);
